edits:
"accountCatalog", "accountBegin", "accountStatus", "accountAnswer", "accountCommit", "accountCancel", "accountOpenBrowser",
            "accountKey" => host.text("選擇憑證檔案", "Choose credential file", "認証ファイルを選択"),
    }
    "accountOpenBrowser" => {
        let result = host.call("accountBrowserURL", args)?;
        let raw = result.as_str().ok_or("Missing login URL")?;
        let url = tauri::Url::parse(raw).map_err(|e| e.to_string())?;
        if url.scheme() != "http" || !matches!(url.host_str(), Some("127.0.0.1") | Some("localhost") | Some("[::1]")) ||
            url.path() != "/auth" || url.port().is_none() || !url.username().is_empty() || url.password().is_some() || url.fragment().is_some() {
            return Err("Invalid local authorization URL".into());
        }
        open_url(raw)?; Ok(Value::Null)

private var accounts: RBNAccountCoordinator!
    accounts = RBNAccountCoordinator(engine: engine, acquire: { [weak self] in
        guard let self else { throw EngineError("程式正在關閉。") }
        try self.controlLock.holding {
            guard !self.closing, !self.configuring, !self.tools.hasActiveSessions else {
                throw EngineError("請先完成帳號設定或播放，再設定帳號。")
            }
            self.configuring = true
        }
    }, release: { [weak self] _ in
        guard let self else { return }
        self.controlLock.holding { self.configuring = false }
        self.event("configurationChanged", data: [:])
    })
    case "accountCatalog", "accountBegin", "accountStatus", "accountAnswer", "accountCommit", "accountCancel", "accountBrowserURL":
        return try accounts.handle(method, arguments)

accounts = RBNAccountCoordinator(engine: engine, acquire: { [weak self] in
    guard let self else { throw EngineError("程式正在關閉。") }
    try self.activityLock.holding {
        guard !self.configuringRemotes, !self.updateInstalling, !self.nativeConnectionChanging,
              !self.terminationValue, !self.toolsManager.hasActiveSessions else {
            throw EngineError("請先完成更新、帳號設定或掛載與播放，再設定帳號。")
        }
        self.configuringRemotes = true
    }
}, release: { [weak self] _ in
    guard let self else { return }
    self.activityLock.holding { self.configuringRemotes = false }
    self.sendEvent(type: "configurationChanged", data: [:])
})

private var completionWindowPresented: Bool {
    guard let window else { return false }
    return NSApp.isActive && window.isVisible && !window.isMiniaturized &&
        window.occlusionState.contains(.visible) && (window.isKeyWindow || window.isMainWindow)
}
private func refreshCompletionAttention(applicationActivated: Bool = false) {
    guard engine != nil else { return }
    completionAttention.reconcile(enabled: engine.settingsSnapshot()["bounceDockOnCompletion"] as? Bool ?? true,
        isWindowPresented: completionWindowPresented, applicationActivated: applicationActivated)
}
func applicationDidResignActive(_ notification: Notification) { refreshCompletionAttention() }
func windowDidBecomeKey(_ notification: Notification) { refreshCompletionAttention() }
func windowDidDeminiaturize(_ notification: Notification) { refreshCompletionAttention() }
func windowDidChangeOcclusionState(_ notification: Notification) { refreshCompletionAttention() }

case "accountCatalog", "accountBegin", "accountStatus", "accountAnswer", "accountCommit", "accountCancel":
    return try accounts.handle(method, arguments)
case "accountOpenBrowser":
    guard let raw = try accounts.handle("accountBrowserURL", arguments) as? String,
          let url = URL(string: raw), RBNAccountSetup.permittedAuthURL(url) else { throw EngineError("登入頁面無法開啟。") }
    guard onMain({ NSWorkspace.shared.open(url) }) else { throw EngineError("無法開啟瀏覽器。") }
    return NSNull()
